import { teacherApi } from './teacher-api.js';

const app = document.querySelector('#teacher-app');
const nav = [
  ['overview','Огляд','⌁'],['groups','Групи','◇'],['classes','Заняття','◷'],['homework','Домашні роботи','▤'],
  ['students','Учні','◎'],['projects','Проєкти','⬡'],['mentoring','Менторство','∞'],['reports','Звіти','◫']
];
const state = { data:null, route:'overview', id:null, tab:'overview', saving:false, dirty:false, searchOpen:false };
const fmt = new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const dateOnly = new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long'});
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const when = value => value ? fmt.format(new Date(value)) : 'Не заплановано';
const statusLabel = {scheduled:'Заплановано',rescheduled:'Перенесено',in_progress:'Триває',completed:'Завершено',cancelled:'Скасовано',draft:'Чернетка',published:'Опубліковано',closed:'Закрито',archived:'Архів',submitted:'Нова робота',needs_revision:'На доопрацювання',reviewed:'Перевірено',ready_for_review:'Готовий до погодження',approved:'Погоджено',sent:'Надіслано',failed:'Помилка',confirmed:'Підтверджено',no_show:'Не зʼявився',open:'Відкрито',blocked:'Заблоковано'};

function parseRoute(){
  const raw=location.hash.slice(1)||'overview'; const [route,id]=raw.split('=');
  if(state.dirty && !confirm('Є незбережені зміни у перевірці. Перейти без збереження?')) { history.back(); return; }
  state.route=route; state.id=id||null; state.dirty=false; state.tab='overview'; render();
}
function go(route,id){ location.hash=id?`${route}=${id}`:route; }
function badge(status){return `<span class="status status--${esc(status)}"><i></i>${esc(statusLabel[status]||status)}</span>`}
function meter(value){return `<div class="meter"><i style="width:${Math.max(0,Math.min(100,value||0))}%"></i></div>`}
function initials(name){return String(name).split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function empty(title,text){return `<div class="empty"><span>＋</span><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`}
function shell(content,title,eyebrow='TEACHER OS'){
  const d=state.data; const active=state.route==='group'?'groups':state.route==='class'||state.route==='attendance'?'classes':state.route==='review'?'homework':state.route==='student'?'students':state.route;
  return `<div class="os-shell">
    <aside class="sidebar">
      <a class="brand" href="#overview"><span class="brand-mark">AI</span><span>STARTUP SCHOOL<small>Teacher OS</small></span></a>
      <nav>${nav.map(([key,label,icon])=>`<a href="#${key}" class="${active===key?'active':''}"><b>${icon}</b><span>${label}</span>${key==='homework'&&d.metrics.awaitingReview?`<em>${d.metrics.awaitingReview}</em>`:''}</a>`).join('')}</nav>
      <div class="side-foot"><div class="avatar">${initials(d.teacher.name)}</div><div><strong>${esc(d.teacher.name)}</strong><small>${esc(d.teacher.title)}</small></div></div>
    </aside>
    <main class="workspace">
      <header class="topbar"><div><span class="eyebrow">${eyebrow}</span><h1>${esc(title)}</h1></div><div class="top-actions"><button class="icon-button" data-action="search" aria-label="Пошук">⌕</button><button class="icon-button" data-action="notice" aria-label="Сповіщення">◌</button><button class="logout-button" data-action="logout">Вийти</button><div class="top-avatar">${initials(d.teacher.name)}</div></div></header>
      <div class="page">${content}</div>
    </main>
    <div class="search-layer ${state.searchOpen?'open':''}"><button data-action="close-search" aria-label="Закрити">×</button><div class="search-box"><span>⌕</span><input id="global-search" placeholder="Учень, група, робота або проєкт" autocomplete="off"><div id="search-results"><p>Почніть вводити — пошук працює лише в межах ваших груп.</p></div></div></div>
    <div id="toast" class="toast"></div>
  </div>`;
}

function overview(){
 const d=state.data, next=d.sessions.filter(x=>['scheduled','rescheduled','in_progress'].includes(x.status)).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt))[0];
 return shell(`<section class="welcome"><div><p>${new Intl.DateTimeFormat('uk-UA',{weekday:'long',day:'numeric',month:'long'}).format(new Date())}</p><h2>Добрий день, ${esc(d.teacher.name.split(' ')[0])}</h2><span>Ось що потребує вашої уваги сьогодні.</span></div><div class="signal"><i></i><span>Система синхронізована</span></div></section>
 <section class="metric-grid">
 ${[['Сьогодні занять',d.metrics.todayClasses,'classes'],['Очікують перевірки',d.metrics.awaitingReview,'homework'],['Повторно надіслані',d.metrics.resubmitted,'homework'],['Менторські зустрічі',d.metrics.mentorToday,'mentoring'],['Звіти до погодження',d.metrics.reportsPending,'reports']].map(([l,v,r],i)=>`<button class="metric-card" data-go="${r}"><span>0${i+1}</span><strong>${v}</strong><p>${l}</p><i>↗</i></button>`).join('')}</section>
 <div class="overview-grid"><section class="panel next-class"><div class="panel-head"><div><span class="kicker">НАСТУПНИЙ ЕФІР</span><h3>${next?esc(next.title):'Занять немає'}</h3></div>${next?badge(next.status):''}</div>${next?`<div class="class-time"><strong>${when(next.startsAt)}</strong><span>${next.durationMinutes} хв · ${esc(next.groupName)}</span></div><div class="class-context"><div><small>Модуль</small><b>${esc(next.moduleTitle||'—')}</b></div><div><small>Урок</small><b>${esc(next.lessonTitle||'—')}</b></div><div><small>Учнів</small><b>${next.attendance.length}</b></div></div><div class="button-row"><button class="primary" data-go="class" data-id="${next.id}">Відкрити заняття</button>${next.meetingUrl?`<a class="secondary" href="${esc(next.meetingUrl)}" target="_blank" rel="noreferrer">Увійти в Meet ↗</a>`:''}</div>`:`<p class="muted">Наступні заняття зʼявляться тут після планування.</p>`}</section>
 <section class="panel"><div class="panel-head"><div><span class="kicker">У ФОКУСІ</span><h3>Потребують уваги</h3></div><button class="text-button" data-go="students">Усі учні →</button></div><div class="attention-list">${d.attention.length?d.attention.slice(0,4).map(item=>`<button data-go="student" data-id="${item.studentId}"><span class="avatar">${initials(item.studentName)}</span><span><strong>${esc(item.studentName)}</strong><small>${esc(item.reasons.join(' · '))}</small></span><i>→</i></button>`).join(''):empty('Усе спокійно','Немає учнів, які зараз потребують окремої уваги.')}</div></section></div>
 <section class="panel route-panel"><div class="panel-head"><div><span class="kicker">ОПЕРАЦІЙНИЙ РИТМ</span><h3>Тиждень у русі</h3></div><span class="muted">Europe/Kyiv</span></div><div class="week-line">${d.sessions.slice(0,5).map((s,i)=>`<button data-go="class" data-id="${s.id}"><i class="node ${s.status}"></i><small>${dateOnly.format(new Date(s.startsAt))}</small><strong>${esc(s.title)}</strong><span>${esc(s.groupName)} · ${new Date(s.startsAt).toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'})}</span></button>`).join('')}</div></section>`, 'Операційний огляд');
}

function groups(){const d=state.data; return shell(`<div class="section-intro"><p>Ваші навчальні потоки, прогрес і найближчі дії в одному контексті.</p><button class="primary" data-action="new-group" disabled title="Групи створює адміністратор">＋ Нова група</button></div><div class="group-grid">${d.groups.map(g=>`<article class="group-card"><div class="group-code">${esc(g.name.match(/\d+/)?.[0]||'AI')}</div><div><span class="kicker">${esc(g.courseTitle)}</span><h2>${esc(g.name)}</h2><p>${esc(g.scheduleLabel)}</p></div><div class="group-stats"><div><span>Учні</span><strong>${g.studentCount}</strong></div><div><span>Відвідування</span><strong>${g.attendanceRate}%</strong></div><div><span>Курс</span><strong>${g.progressPercent}%</strong></div></div>${meter(g.progressPercent)}<div class="group-next"><span>Наступне заняття</span><b>${when(g.nextClassAt)}</b></div><button class="secondary full" data-go="group" data-id="${g.id}">Відкрити групу →</button></article>`).join('')}</div>`, 'Групи', 'НАВЧАЛЬНІ ПОТОКИ')}

function groupDetail(){const d=state.data,g=d.groups.find(x=>x.id===state.id)||d.groups[0], students=d.students.filter(x=>x.groupId===g.id), sessions=d.sessions.filter(x=>x.groupId===g.id), hw=d.homework.filter(x=>x.groupId===g.id); return shell(`<button class="back" data-go="groups">← Усі групи</button><section class="group-hero"><div><span class="kicker">${esc(g.courseTitle)}</span><h2>${esc(g.name)}</h2><p>${esc(g.scheduleLabel)} · ${g.studentCount} учнів</p></div><div class="group-progress"><strong>${g.progressPercent}%</strong><span>пройдено курсу</span>${meter(g.progressPercent)}</div></section><div class="tabs"><button class="active">Огляд</button><button data-go="students">Учні</button><button data-go="classes">Заняття</button><button data-go="homework">Домашні роботи</button></div><div class="detail-grid"><section class="panel"><div class="panel-head"><h3>Склад групи</h3><span class="muted">${students.length} учнів</span></div><div class="table-list">${students.map(s=>`<button data-go="student" data-id="${s.id}"><span class="avatar">${initials(s.firstName)}</span><span class="grow"><strong>${esc(s.firstName)}</strong><small>${esc(s.projectTitle||'Проєкт ще не створено')}</small></span><span class="progress-cell">${s.progressPercent}% ${meter(s.progressPercent)}</span><i>→</i></button>`).join('')}</div></section><aside><section class="panel mini"><span class="kicker">НАЙБЛИЖЧЕ ЗАНЯТТЯ</span>${sessions[0]?`<h3>${esc(sessions[0].title)}</h3><p>${when(sessions[0].startsAt)}</p><button class="text-button" data-go="class" data-id="${sessions[0].id}">Підготувати →</button>`:'<p>Не заплановано</p>'}</section><section class="panel mini"><span class="kicker">ДОМАШНЯ РОБОТА</span><h3>${hw[0]?esc(hw[0].title):'Немає активної'}</h3><p>${hw[0]?`${hw[0].submissionCount}/${g.studentCount} надіслали`:'Створіть перше завдання'}</p></section></aside></div>`, g.name, 'ГРУПА')}

function classes(){const d=state.data;return shell(`<div class="section-intro"><p>Керуйте ефірами, матеріалами, статусами та відвідуванням.</p><button class="primary" data-action="new-class">＋ Запланувати заняття</button></div><section class="panel"><div class="filter-row"><button class="active">Усі</button><button>Цього тижня</button><button>Завершені</button><button>Скасовані</button></div><div class="session-list">${d.sessions.map(s=>`<article><div class="date-tile"><strong>${new Date(s.startsAt).getDate()}</strong><span>${new Intl.DateTimeFormat('uk-UA',{month:'short'}).format(new Date(s.startsAt))}</span></div><div class="session-main"><div>${badge(s.status)}<h3>${esc(s.title)}</h3><p>${esc(s.groupName)} · ${esc(s.moduleTitle||'Без модуля')}</p></div><div class="session-meta"><strong>${new Date(s.startsAt).toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'})}</strong><span>${s.durationMinutes} хв</span></div><div class="session-actions"><button class="secondary" data-go="attendance" data-id="${s.id}">Відвідування</button><button class="icon-button" data-go="class" data-id="${s.id}">→</button></div></div></article>`).join('')}</div></section>`, 'Заняття', 'РОЗКЛАД І КЛАС')}

function classDetail(){const d=state.data,s=d.sessions.find(x=>x.id===state.id)||d.sessions[0];return shell(`<button class="back" data-go="classes">← Розклад</button><section class="class-hero"><div><div>${badge(s.status)}<span class="kicker">${esc(s.groupName)}</span></div><h2>${esc(s.title)}</h2><p>${esc(s.description||'Опис заняття ще не додано.')}</p><div class="hero-meta"><span><small>Час</small><strong>${when(s.startsAt)}</strong></span><span><small>Тривалість</small><strong>${s.durationMinutes} хв</strong></span><span><small>Урок</small><strong>${esc(s.lessonTitle||'Не привʼязано')}</strong></span></div></div><div class="hero-actions">${s.meetingUrl?`<a class="primary" href="${esc(s.meetingUrl)}" target="_blank" rel="noreferrer">Приєднатися до ефіру ↗</a>`:''}<button class="secondary" data-action="complete-class" data-id="${s.id}">Позначити завершеним</button><button class="danger-link" data-action="cancel-class" data-id="${s.id}">Скасувати заняття</button></div></section><div class="detail-grid"><section class="panel"><div class="panel-head"><div><span class="kicker">ПЛАН ЗАНЯТТЯ</span><h3>Контекст і матеріали</h3></div><button class="secondary" data-action="add-material" data-id="${s.id}">＋ Додати</button></div><div class="lesson-link"><i>01</i><span><small>${esc(s.moduleTitle||'Модуль')}</small><strong>${esc(s.lessonTitle||'Оберіть урок')}</strong></span></div><div class="material-list">${s.materials.length?s.materials.map(m=>`<a href="${esc(m.url||'#')}" target="_blank" rel="noreferrer"><span>${m.kind==='presentation'?'▱':'↗'}</span><strong>${esc(m.title)}</strong><small>${esc(m.kind)}</small></a>`).join(''):empty('Матеріалів ще немає','Додайте презентацію або корисне посилання.')}</div><label class="field"><span>Приватні нотатки викладача</span><textarea id="class-note" placeholder="Учні та батьки не бачать ці нотатки">${esc(s.teacherNotes)}</textarea></label><button class="secondary" data-action="save-class-note" data-id="${s.id}">Зберегти нотатку</button></section><aside><section class="panel mini"><span class="kicker">ГРУПА</span><h3>${esc(s.groupName)}</h3><p>${s.attendance.length} учнів у списку</p><button class="primary full" data-go="attendance" data-id="${s.id}">Відкрити відвідування</button></section><section class="panel mini"><span class="kicker">ДОМАШНЯ РОБОТА</span><p>${s.homeworkIds.length?`${s.homeworkIds.length} завдання привʼязано`:'Ще не створено'}</p><button class="text-button" data-go="homework">Перейти до завдань →</button></section></aside></div>`, s.title, 'ЗАНЯТТЯ')}

function attendance(){const d=state.data,s=d.sessions.find(x=>x.id===state.id)||d.sessions[0];return shell(`<button class="back" data-go="class" data-id="${s.id}">← До заняття</button><section class="attendance-head"><div><span class="kicker">${esc(s.groupName)} · ${when(s.startsAt)}</span><h2>Відвідування</h2><p>Підтвердьте статуси одним проходом. Підказки системи позначені окремо.</p></div><div><button class="secondary" data-action="mark-all" data-status="present">Усі присутні</button><button class="primary" data-action="save-attendance" data-id="${s.id}">Зберегти</button></div></section><section class="panel attendance-panel"><div class="attendance-summary"><span><b>${s.attendance.length}</b> у групі</span><span><b>${s.attendance.filter(x=>x.status==='present').length}</b> присутні</span><span><b>${s.attendance.filter(x=>x.status==='late').length}</b> запізнились</span><small>Статуси не зберігаються автоматично</small></div><div class="attendance-list">${s.attendance.map((a,i)=>`<div class="attendance-row" data-student="${a.studentId}"><span class="row-number">${String(i+1).padStart(2,'0')}</span><span class="avatar">${initials(a.studentName)}</span><strong>${esc(a.studentName)}</strong><div class="segmented">${[['present','Присутній'],['late','Запізнився'],['absent','Відсутній'],['excused','Поважна']].map(([v,l])=>`<label><input type="radio" name="att-${a.studentId}" value="${v}" ${(a.status||a.suggestedStatus)==v?'checked':''}><span>${l}</span></label>`).join('')}</div><input class="note-input" value="${esc(a.note)}" placeholder="Нотатка"><span class="suggested">${a.suggestedStatus&&!a.status?'підказка':''}</span></div>`).join('')}</div></section>`, 'Відвідування', 'ШВИДКЕ ПІДТВЕРДЖЕННЯ')}

function homework(){const d=state.data;return shell(`<div class="section-intro"><p>Створення, публікація та черга перевірки без втрати контексту.</p><button class="primary" data-action="new-homework">＋ Створити завдання</button></div><div class="homework-summary"><span><strong>${d.homework.length}</strong> завдань</span><span><strong>${d.metrics.awaitingReview}</strong> очікують перевірки</span><span><strong>${d.metrics.resubmitted}</strong> повторних спроб</span></div><div class="homework-layout"><section class="panel"><div class="panel-head"><div><span class="kicker">ЗАВДАННЯ</span><h3>Активні домашні роботи</h3></div></div><div class="assignment-list">${d.homework.map(h=>`<article><div><div>${badge(h.status)}<span class="muted">${esc(h.groupName)}</span></div><h3>${esc(h.title)}</h3><p>${esc(h.instructions)}</p></div><div class="submission-ring"><strong>${h.submissionCount}</strong><span>робіт</span></div><div class="assignment-stats"><span>Перевірено <b>${h.reviewCount}</b></span><span>Доопрацювання <b>${h.needsRevisionCount}</b></span><span>Дедлайн <b>${h.dueAt?dateOnly.format(new Date(h.dueAt)):'—'}</b></span></div>${h.status==='draft'?`<button class="secondary" data-action="publish-homework" data-id="${h.id}">Опублікувати</button>`:''}</article>`).join('')}</div></section><aside class="panel queue"><div class="panel-head"><div><span class="kicker">ЧЕРГА</span><h3>Перевірити зараз</h3></div><b>${d.submissions.filter(x=>!x.review||x.status==='needs_revision').length}</b></div>${d.submissions.filter(x=>!x.review||x.status==='needs_revision').map(s=>`<button data-go="review" data-id="${s.id}"><span class="avatar">${initials(s.studentName)}</span><span><strong>${esc(s.studentName)}</strong><small>${esc(s.homeworkTitle)} · спроба ${s.attemptNumber}</small></span>${badge(s.status)}<i>→</i></button>`).join('')||empty('Черга порожня','Усі надіслані роботи перевірено.')}</aside></div>`, 'Домашні роботи', 'ЗАВДАННЯ І ПЕРЕВІРКА')}

function review(){const d=state.data,s=d.submissions.find(x=>x.id===state.id)||d.submissions[0], queue=d.submissions.filter(x=>!x.review||x.status==='needs_revision'),idx=queue.findIndex(x=>x.id===s.id), prev=queue[idx-1],next=queue[idx+1];return shell(`<div class="review-nav"><button class="back" data-go="homework">← До черги</button><div><button class="secondary" ${!prev?'disabled':''} data-go="review" data-id="${prev?.id||''}">← Попередня</button><span>${idx+1} / ${queue.length}</span><button class="secondary" ${!next?'disabled':''} data-go="review" data-id="${next?.id||''}">Наступна →</button></div></div><div class="review-grid"><section><div class="review-title"><div class="avatar large">${initials(s.studentName)}</div><div><span class="kicker">${esc(s.groupName)} · СПРОБА ${s.attemptNumber}</span><h2>${esc(s.studentName)}</h2><p>${esc(s.homeworkTitle)}</p></div>${badge(s.status)}</div><article class="student-work"><span class="kicker">ВІДПОВІДЬ УЧНЯ</span><p>${esc(s.contentText||'Текстову відповідь не додано.')}</p>${s.contentUrl?`<a class="work-link" href="${esc(s.contentUrl)}" target="_blank" rel="noreferrer">Відкрити роботу ↗</a>`:''}${s.studentComment?`<blockquote>${esc(s.studentComment)}</blockquote>`:''}</article>${s.previousAttempts.length?`<details class="previous"><summary>Попередні спроби (${s.previousAttempts.length})</summary>${s.previousAttempts.map(a=>`<p>${esc(a.contentText)}</p>`).join('')}</details>`:''}</section><aside class="panel review-form"><span class="kicker">ОЦІНЮВАННЯ</span><label class="field"><span>Оцінка · <b id="score-value">${s.review?.score||8}</b>/10</span><input id="review-score" type="range" min="0" max="10" value="${s.review?.score||8}"></label><label class="field"><span>Зусилля</span><select id="review-effort"><option value="high_effort">Високі зусилля</option><option value="good_effort">Хороші зусилля</option><option value="needs_attention">Потребує уваги</option></select></label><label class="field"><span>Рішення</span><select id="review-status"><option value="completed">Завершено</option><option value="needs_revision">Повернути на доопрацювання</option><option value="reviewed">Перевірено</option></select></label><label class="field"><span>Зворотний звʼязок</span><textarea id="review-feedback" placeholder="Конкретно: що вдалося і який наступний крок">${esc(s.review?.feedback||'')}</textarea></label><p class="privacy-note">Цей коментар побачить учень. Приватні нотатки зберігаються окремо.</p><button class="primary full" data-action="save-review" data-id="${s.id}">Зберегти перевірку</button></aside></div>`, 'Перевірка роботи', 'РОБОЧЕ МІСЦЕ ВИКЛАДАЧА')}

function students(){const d=state.data;return shell(`<div class="section-intro"><p>Приватний робочий реєстр ваших учнів і прозорі сигнали уваги.</p><button class="secondary" data-action="search">⌕ Знайти учня</button></div><section class="panel"><div class="student-table"><div class="table-head"><span>Учень</span><span>Група</span><span>Прогрес</span><span>Домашні</span><span>Відвідування</span><span>Сигнали</span><span></span></div>${d.students.map(s=>{const total=Object.values(s.attendance).reduce((a,b)=>a+b,0),rate=total?Math.round(s.attendance.present/total*100):0;return `<button data-go="student" data-id="${s.id}"><span class="student-id"><i class="avatar">${initials(s.firstName)}</i><i><strong>${esc(s.firstName)}</strong><small>${esc(s.projectTitle||'Без проєкту')}</small></i></span><span>${esc(s.groupName)}</span><span><b>${s.progressPercent}%</b>${meter(s.progressPercent)}</span><span>${s.homework.submitted}/${s.homework.assigned}</span><span>${rate}%</span><span>${s.attentionReasons.length?`<em>${s.attentionReasons.length} причини</em>`:'У нормі'}</span><span>→</span></button>`}).join('')}</div></section>`, 'Учні', 'НАВЧАЛЬНИЙ КОНТЕКСТ')}

function student(){const d=state.data,s=d.students.find(x=>x.id===state.id)||d.students[0], tabs=['overview','learning','homework','projects','portfolio','mentoring','notes']; const tabNames={overview:'Огляд',learning:'Навчання',homework:'Домашні',projects:'Проєкти',portfolio:'Портфоліо',mentoring:'Менторство',notes:'Нотатки'};let content='';if(state.tab==='notes')content=`<section class="panel"><div class="panel-head"><div><span class="kicker">ПРИВАТНО</span><h3>Нотатки викладача</h3></div><span class="lock">◉ Не бачать учень і батьки</span></div><label class="field"><span>Нова нотатка</span><textarea id="student-note" placeholder="Спостереження, домовленості, наступний крок"></textarea></label><div class="button-row"><select id="note-category"><option value="general">Загальна</option><option value="learning">Навчання</option><option value="project">Проєкт</option><option value="mentoring">Менторство</option></select><button class="primary" data-action="add-note" data-id="${s.id}">Додати нотатку</button></div><div class="note-timeline">${s.notes.map(n=>`<article><i></i><div><span>${esc(n.category)} · ${when(n.createdAt)}</span><p>${esc(n.content)}</p></div></article>`).join('')||empty('Нотаток немає','Додайте перше приватне спостереження.')}</div></section>`;else if(state.tab==='portfolio')content=`<section class="panel"><div class="panel-head"><div><span class="kicker">ПРИВАТНЕ ПОРТФОЛІО</span><h3>${esc(s.portfolio?.title||'Портфоліо')}</h3></div><span>${s.portfolio?.projects.length||0} робіт</span></div><div class="portfolio-grid">${s.portfolio?.projects.map(p=>`<article><div class="project-orbit">${initials(p.title)}</div><h3>${esc(p.title)}</h3><p>${esc(p.shortDescription)}</p><div class="tag-row">${p.technologies.map(t=>`<span>${esc(t)}</span>`).join('')}</div><button class="text-button" data-action="edit-portfolio" data-id="${p.id}">Редагувати опис →</button></article>`).join('')||empty('Портфоліо формується','Завершені проєкти зʼявляться тут після додавання учнем.')}</div></section>`;else content=`<div class="student-overview"><section class="panel"><span class="kicker">НАВЧАЛЬНИЙ ПРОГРЕС</span><div class="big-progress"><strong>${s.progressPercent}%</strong><div><h3>${esc(s.moduleTitle)}</h3><p>${esc(s.courseTitle)}</p>${meter(s.progressPercent)}</div></div><div class="student-metrics"><span><b>${s.xp}</b> XP</span><span><b>${s.homework.averageScore??'—'}</b> середня оцінка</span><span><b>${s.homework.submitted}/${s.homework.assigned}</b> домашні</span><span><b>${s.attendance.present}</b> відвідано</span></div></section><section class="panel"><span class="kicker">АКТИВНИЙ ПРОЄКТ</span>${s.projects[0]?`<h3>${esc(s.projects[0].title)}</h3><p>${esc(s.projects[0].summary)}</p><div class="project-stage"><span>${esc(s.projects[0].stage.title)}</span><b>${s.projects[0].completionPercent}%</b></div>${meter(s.projects[0].completionPercent)}<button class="text-button" data-go="projects">Відкрити проєкт →</button>`:empty('Проєкт ще не створено','Учень зможе почати його в Student App.')}</section>${s.attentionReasons.length?`<section class="panel attention-detail"><span class="kicker">ПОТРЕБУЄ УВАГИ</span>${s.attentionReasons.map(r=>`<p><i>!</i>${esc(r)}</p>`).join('')}</section>`:''}</div>`;return shell(`<button class="back" data-go="students">← Усі учні</button><section class="student-hero"><div class="avatar xlarge">${initials(s.firstName)}</div><div><span class="kicker">${esc(s.groupName)}</span><h2>${esc(s.firstName)}</h2><p>${esc(s.level)} · остання активність ${s.recentActivityAt?when(s.recentActivityAt):'не зафіксована'}</p></div><span class="xp-badge">${s.xp} XP</span></section><div class="tabs student-tabs">${tabs.map(t=>`<button class="${state.tab===t?'active':''}" data-tab="${t}">${tabNames[t]}</button>`).join('')}</div>${content}`, s.firstName, 'КАРТКА УЧНЯ')}

function projects(){
 const d=state.data, projects=d.students.flatMap(s=>s.projects.map(p=>({...p,studentId:s.id,studentName:s.firstName,groupName:s.groupName,portfolio:s.portfolio?.projects.find(x=>x.projectId===p.id)})));
 return shell(`<div class="section-intro"><p>Живий зріз продуктів: стадія, наступна задача і готовність до приватного портфоліо.</p><span class="muted">${projects.length} активних проєктів</span></div><div class="project-board">${projects.map((p,i)=>{const nextTask=p.tasks.find(task=>['available','in_progress'].includes(task.status));return `<article><div class="project-visual"><span>0${i+1}</span><div class="orbit"><i></i></div><b>${p.completionPercent}%</b></div><div class="project-owner"><span class="avatar">${initials(p.studentName)}</span><span><strong>${esc(p.studentName)}</strong><small>${esc(p.groupName)}</small></span><em class="portfolio-state">${p.portfolio?'У портфоліо':'Не додано'}</em></div><h2>${esc(p.title)}</h2><p>${esc(p.summary)}</p><div class="stage-line"><span>${esc(p.stage.title)}</span><b>${p.stage.position}/${p.stage.total}</b></div>${meter(p.completionPercent)}<div class="next-task"><small>НАСТУПНА ЗАДАЧА</small><strong>${esc(nextTask?.title||'Усі задачі завершено')}</strong></div><div class="tag-row">${p.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="button-row">${p.workspaceUrl?`<a class="text-button" href="${esc(p.workspaceUrl)}" target="_blank" rel="noreferrer">Відкрити демо ↗</a>`:''}<button class="secondary" data-go="student" data-id="${p.studentId}">Контекст учня →</button></div></article>`}).join('')||empty('Проєктів ще немає','Активні продукти ваших учнів зʼявляться тут.')}</div>`, 'Проєкти учнів', 'ПРОДУКТОВА ЛАБОРАТОРІЯ')
}

function mentoring(){const d=state.data;return shell(`<div class="section-intro"><p>Слоти й зустрічі, привʼязані до реального контексту учня та проєкту.</p><button class="primary" data-action="new-slot">＋ Відкрити слот</button></div><div class="mentor-grid"><section class="panel"><div class="panel-head"><div><span class="kicker">НАЙБЛИЖЧІ ЗУСТРІЧІ</span><h3>Менторська черга</h3></div></div><div class="booking-list">${d.mentor.bookings.map(b=>`<article><div class="booking-time"><strong>${new Date(b.startsAt).getDate()}</strong><span>${new Intl.DateTimeFormat('uk-UA',{month:'short'}).format(new Date(b.startsAt))}</span><small>${new Date(b.startsAt).toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'})}</small></div><div><div>${badge(b.status)}<span class="muted">${esc(b.projectTitle||'Загальна консультація')}</span></div><h3>${esc(b.studentName)}</h3><p>${Math.round((new Date(b.endsAt)-new Date(b.startsAt))/60000)} хв · ${esc(b.mentorName)}</p></div><div class="booking-actions"><button class="secondary" data-go="student" data-id="${b.studentId}">Контекст учня</button>${b.status==='reserved'?`<button class="primary" data-action="confirm-booking" data-id="${b.id}">Підтвердити</button>`:''}</div></article>`).join('')||empty('Зустрічей немає','Нові бронювання учнів зʼявляться тут.')}</div></section><aside class="panel"><div class="panel-head"><div><span class="kicker">ДОСТУПНІСТЬ</span><h3>Ваші слоти</h3></div></div><div class="availability-list">${d.mentor.availability.map(a=>`<div><i class="node ${a.status}"></i><span><strong>${when(a.startsAt)}</strong><small>${Math.round((new Date(a.endsAt)-new Date(a.startsAt))/60000)} хв · ${esc(a.timezone)}</small></span>${badge(a.status)}</div>`).join('')||empty('Немає відкритих слотів','Додайте доступний час для учнів.')}</div></aside></div>`, 'Менторство', 'КОНСУЛЬТАЦІЇ')}

function reports(){const d=state.data;return shell(`<div class="section-intro"><p>Щотижневий прогрес для батьків — тільки після явного погодження викладачем.</p><button class="primary" data-action="generate-reports">＋ Згенерувати чернетки</button></div><div class="report-flow"><span class="done">1 <b>Чернетка</b></span><i></i><span>2 <b>Перевірка</b></span><i></i><span>3 <b>Погодження</b></span><i></i><span>4 <b>Надсилання</b></span></div><section class="panel"><div class="report-list">${d.reports.map(r=>`<article><div class="report-student"><span class="avatar">${initials(r.studentFirstName)}</span><span><strong>${esc(r.studentFirstName)}</strong><small>${esc(r.groupName)} · ${dateOnly.format(new Date(r.periodStart))}—${dateOnly.format(new Date(r.periodEnd))}</small></span></div>${badge(r.status)}<div class="report-facts"><span>XP <b>${esc(r.payload.xpEarned??'—')}</b></span><span>Проєкт <b>${esc(r.payload.projectProgress??'—')}%</b></span><span>Заняття <b>${esc(r.payload.classesAttended??'—')}/${esc(r.payload.classesScheduled??'—')}</b></span></div><p>${esc(r.teacherComment||'Коментар викладача ще не додано.')}</p><div class="button-row"><button class="secondary" data-action="edit-report" data-id="${r.id}">Редагувати</button>${r.status==='ready_for_review'?`<button class="primary" data-action="approve-report" data-id="${r.id}">Погодити звіт</button>`:''}</div></article>`).join('')||empty('Звітів ще немає','Згенеруйте тижневі чернетки для вибраної групи.')}</div></section>`, 'Звіти', 'ПРОГРЕС ДЛЯ БАТЬКІВ')}

function render(){if(!state.data)return; const screens={overview,groups,group:groupDetail,classes,class:classDetail,attendance,homework,review,students,student,projects,mentoring,reports};app.innerHTML=(screens[state.route]||overview)();bind();}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`toast show ${error?'error':''}`;setTimeout(()=>el.classList.remove('show'),2600)}
async function refresh(message){state.data=await teacherApi.workspace();render();if(message)setTimeout(()=>toast(message),20)}
function localValue(value){const date=value?new Date(value):new Date(Date.now()+86400000);date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,16)}
function openModal(title,body,onSubmit){
 const layer=document.createElement('div');layer.className='modal-layer';layer.innerHTML=`<form class="modal"><div class="modal-head"><div><span class="kicker">TEACHER OS</span><h2>${esc(title)}</h2></div><button type="button" aria-label="Закрити">×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button type="button" class="secondary">Скасувати</button><button class="primary" type="submit">Зберегти</button></div></form>`;document.body.append(layer);
 const close=()=>layer.remove();layer.addEventListener('click',event=>{if(event.target===layer)close()});layer.querySelector('.modal-head button').onclick=close;layer.querySelector('.modal-actions .secondary').onclick=close;
 layer.querySelector('form').onsubmit=async event=>{event.preventDefault();const submit=layer.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Зберігаємо…';try{await onSubmit(new FormData(event.currentTarget));close()}catch(error){toast(error.message,true);submit.disabled=false;submit.textContent='Зберегти'}};
}
function bind(){
 if(state.route==='review'){const submission=state.data.submissions.find(item=>item.id===state.id);if(submission?.review){document.querySelector('#review-effort').value=submission.review.effort;document.querySelector('#review-status').value=submission.review.status}}
 if(state.route==='class'){const actions=document.querySelector('.hero-actions');const complete=actions?.querySelector('[data-action="complete-class"]');if(actions&&complete)complete.insertAdjacentHTML('beforebegin',`<button class="secondary" data-action="edit-class" data-id="${state.id}">Редагувати</button><button class="secondary" data-action="reschedule-class" data-id="${state.id}">Перенести</button>`)}
 if(state.route==='homework'){
   const groupOptions=state.data.groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('');
   const homeworkOptions=state.data.homework.map(h=>`<option value="${h.id}">${esc(h.title)}</option>`).join('');
   const summary=document.querySelector('.homework-summary');summary?.insertAdjacentHTML('afterend',`<div class="queue-filters"><span>Фільтри черги</span><select id="filter-group"><option value="">Усі групи</option>${groupOptions}</select><select id="filter-homework"><option value="">Усі завдання</option>${homeworkOptions}</select><select id="filter-state"><option value="">Усі стани</option><option value="submitted">Надіслані</option><option value="resubmitted">Повторні</option><option value="needs_revision">На доопрацюванні</option></select><input id="filter-date" type="date" aria-label="Дата надсилання"><button class="text-button" id="clear-filters">Скинути</button></div>`);
   const applyFilters=()=>{const group=document.querySelector('#filter-group').value,homework=document.querySelector('#filter-homework').value,status=document.querySelector('#filter-state').value,date=document.querySelector('#filter-date').value;document.querySelectorAll('.queue>button[data-id]').forEach(button=>{const item=state.data.submissions.find(x=>x.id===button.dataset.id);const matches=(!group||item.groupId===group)&&(!homework||item.homeworkId===homework)&&(!date||item.submittedAt?.slice(0,10)===date)&&(!status||(status==='resubmitted'?item.attemptNumber>1:item.status===status));button.hidden=!matches})};
   ['#filter-group','#filter-homework','#filter-state','#filter-date'].forEach(selector=>document.querySelector(selector)?.addEventListener('input',applyFilters));document.querySelector('#clear-filters')?.addEventListener('click',()=>{['#filter-group','#filter-homework','#filter-state','#filter-date'].forEach(selector=>document.querySelector(selector).value='');applyFilters()});
 }
 if(state.route==='mentoring')document.querySelectorAll('.booking-list article').forEach((article,index)=>{const booking=state.data.mentor.bookings[index],actions=article.querySelector('.booking-actions');if(!booking||!actions)return;if(['reserved','confirmed','rescheduled'].includes(booking.status))actions.insertAdjacentHTML('beforeend',`<button class="secondary" data-action="reschedule-booking" data-id="${booking.id}">Перенести</button><button class="danger-link" data-action="cancel-booking" data-id="${booking.id}">Скасувати</button>`);if(['confirmed','rescheduled'].includes(booking.status))actions.insertAdjacentHTML('beforeend',`<button class="primary" data-action="complete-booking" data-id="${booking.id}">Завершити</button>`)});
 document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',()=>{if(!el.disabled)go(el.dataset.go,el.dataset.id)}));
 document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>{state.tab=el.dataset.tab;render()}));
 document.querySelector('[data-action="search"]')?.addEventListener('click',()=>{state.searchOpen=true;document.querySelector('.search-layer').classList.add('open');setTimeout(()=>document.querySelector('#global-search')?.focus(),20)});
 document.querySelector('[data-action="close-search"]')?.addEventListener('click',()=>{state.searchOpen=false;document.querySelector('.search-layer').classList.remove('open')});
 const search=document.querySelector('#global-search'); let timer; search?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const target=document.querySelector('#search-results');if(search.value.trim().length<2){target.innerHTML='<p>Введіть щонайменше 2 символи.</p>';return}try{const result=await teacherApi.search(search.value);target.innerHTML=Object.entries(result).flatMap(([kind,items])=>items.map(item=>`<button data-kind="${kind}" data-id="${item.id}"><strong>${esc(item.label)}</strong><small>${esc(item.meta)}</small></button>`)).join('')||'<p>Нічого не знайдено у ваших групах.</p>';target.querySelectorAll('button').forEach(b=>b.onclick=()=>{const map={students:'student',groups:'group',homework:'homework',projects:'projects'};state.searchOpen=false;go(map[b.dataset.kind],b.dataset.id)})}catch(e){target.innerHTML=`<p>${esc(e.message)}</p>`}},260)});
 document.querySelector('#review-score')?.addEventListener('input',e=>{document.querySelector('#score-value').textContent=e.target.value;state.dirty=true});
 ['#review-effort','#review-status','#review-feedback'].forEach(sel=>document.querySelector(sel)?.addEventListener('input',()=>state.dirty=true));
 document.querySelector('[data-action="mark-all"]')?.addEventListener('click',()=>document.querySelectorAll('.attendance-row input[value="present"]').forEach(i=>i.checked=true));
 document.querySelectorAll('[data-action]').forEach(el=>{if(['search','close-search','mark-all'].includes(el.dataset.action))return;el.addEventListener('click',()=>action(el.dataset.action,el.dataset.id))});
}
async function action(name,id){try{
 if(name==='logout'){await teacherApi.logout();location.replace('/login.html?next=%2Fteacher.html');return}
 if(state.saving)return;state.saving=true;
 if(name==='complete-class'||name==='cancel-class'){await teacherApi.updateClass(id,{status:name==='complete-class'?'completed':'cancelled'});await refresh(name==='complete-class'?'Заняття завершено':'Заняття скасовано')}
 if(name==='save-class-note'){await teacherApi.updateClass(id,{teacherNotes:document.querySelector('#class-note').value});await refresh('Приватну нотатку збережено')}
 if(name==='save-attendance'){const entries=[...document.querySelectorAll('.attendance-row')].map(row=>({studentId:row.dataset.student,status:row.querySelector('input:checked')?.value||'present',note:row.querySelector('.note-input').value}));await teacherApi.saveAttendance(id,entries);await refresh('Відвідування підтверджено')}
 if(name==='publish-homework'){await teacherApi.publishHomework(id);await refresh('Завдання опубліковано')}
 if(name==='save-review'){const queue=state.data.submissions.filter(item=>!item.review||item.status==='needs_revision'),next=queue[queue.findIndex(item=>item.id===id)+1];await teacherApi.review(id,{score:Number(document.querySelector('#review-score').value),effort:document.querySelector('#review-effort').value,status:document.querySelector('#review-status').value,feedback:document.querySelector('#review-feedback').value});state.dirty=false;await refresh('Перевірку збережено');go(next?'review':'homework',next?.id)}
 if(name==='add-note'){const content=document.querySelector('#student-note').value.trim();if(!content)throw new Error('Додайте текст нотатки');await teacherApi.addNote(id,{category:document.querySelector('#note-category').value,content});await refresh('Приватну нотатку додано')}
 if(name==='confirm-booking'){await teacherApi.updateBooking(id,{status:'confirmed'});await refresh('Зустріч підтверджено')}
 if(name==='complete-booking'){await teacherApi.updateBooking(id,{status:'completed'});await refresh('Зустріч завершено')}
 if(name==='cancel-booking'){if(!confirm('Скасувати цю менторську зустріч?'))return;await teacherApi.updateBooking(id,{status:'cancelled'});await refresh('Зустріч скасовано')}
 if(name==='reschedule-booking'){const booking=state.data.mentor.bookings.find(item=>item.id===id);openModal('Перенести менторську зустріч',`<label class="field"><span>Новий початок</span><input name="startsAt" type="datetime-local" value="${localValue(booking.startsAt)}" required></label><label class="field"><span>Новий кінець</span><input name="endsAt" type="datetime-local" value="${localValue(booking.endsAt)}" required></label><label class="field"><span>HTTPS-посилання</span><input name="meetingUrl" type="url" value="${esc(booking.meetingUrl||'')}"></label>`,async form=>{await teacherApi.updateBooking(id,{status:'rescheduled',startsAt:new Date(form.get('startsAt')).toISOString(),endsAt:new Date(form.get('endsAt')).toISOString(),meetingUrl:form.get('meetingUrl')||null});await refresh('Зустріч перенесено')});}
 if(name==='approve-report'){if(!confirm('Погодити цей звіт для подальшого надсилання батькам?'))return;await teacherApi.approveReport(id);await refresh('Звіт погоджено')}
 if(name==='generate-reports'){const g=state.data.groups[0],end=new Date(),start=new Date(end);start.setDate(end.getDate()-7);await teacherApi.generateReports({groupId:g.id,periodStart:start.toISOString().slice(0,10),periodEnd:end.toISOString().slice(0,10)});await refresh('Чернетки звітів створено')}
 if(name==='new-slot'){const start=new Date(Date.now()+86400000);start.setHours(16,0,0,0);openModal('Новий менторський слот',`<label class="field"><span>Початок</span><input name="startsAt" type="datetime-local" value="${localValue(start)}" required></label><label class="field"><span>Тривалість</span><select name="duration"><option value="30">30 хв</option><option value="45">45 хв</option><option value="60">60 хв</option></select></label><label class="field"><span>Тип вікна</span><select name="status"><option value="open">Доступно для бронювання</option><option value="blocked">Заблокований час</option></select></label>`,async form=>{const startsAt=new Date(form.get('startsAt')),endsAt=new Date(startsAt.getTime()+Number(form.get('duration'))*60000);await teacherApi.createAvailability({startsAt:startsAt.toISOString(),endsAt:endsAt.toISOString(),timezone:state.data.teacher.timezone,status:form.get('status')});await refresh('Новий слот відкрито')});}
 if(name==='add-material'){const title=prompt('Назва матеріалу');if(!title)return;const url=prompt('HTTPS-посилання');if(!url)return;await teacherApi.addMaterial(id,{kind:'link',title,url});await refresh('Матеріал додано')}
 if(name==='new-class'){const group=state.data.groups[0],start=new Date(Date.now()+86400000);start.setHours(17,0,0,0);openModal('Запланувати заняття',`<div class="form-grid"><label class="field"><span>Група</span><select name="groupId">${state.data.groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`)}</select></label><label class="field"><span>Урок</span><select name="lessonId"><option value="">Без привʼязки</option>${state.data.lessons.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`)}</select></label></div><label class="field"><span>Тема</span><input name="title" required maxlength="160"></label><label class="field"><span>Опис</span><textarea name="description"></textarea></label><div class="form-grid"><label class="field"><span>Початок</span><input name="startsAt" type="datetime-local" value="${localValue(start)}" required></label><label class="field"><span>Тривалість</span><select name="duration"><option value="90">90 хв</option><option value="60">60 хв</option><option value="45">45 хв</option></select></label></div><label class="field"><span>HTTPS-посилання на зустріч</span><input name="meetingUrl" type="url" placeholder="https://…"></label>`,async form=>{const selected=state.data.groups.find(g=>g.id===form.get('groupId'))||group,startsAt=new Date(form.get('startsAt')),endsAt=new Date(startsAt.getTime()+Number(form.get('duration'))*60000);const input={groupId:selected.id,courseId:selected.courseId,title:form.get('title'),description:form.get('description'),startsAt:startsAt.toISOString(),endsAt:endsAt.toISOString(),meetingProvider:'External'};if(form.get('lessonId'))input.lessonId=form.get('lessonId');if(form.get('meetingUrl'))input.meetingUrl=form.get('meetingUrl');await teacherApi.createClass(input);await refresh('Заняття заплановано')});}
 if(name==='edit-class'){const item=state.data.sessions.find(x=>x.id===id);openModal('Редагувати заняття',`<label class="field"><span>Тема</span><input name="title" value="${esc(item.title)}" required></label><label class="field"><span>Опис</span><textarea name="description">${esc(item.description)}</textarea></label><label class="field"><span>Урок</span><select name="lessonId"><option value="">Без привʼязки</option>${state.data.lessons.map(l=>`<option value="${l.id}" ${l.id===item.lessonId?'selected':''}>${esc(l.title)}</option>`)}</select></label><label class="field"><span>HTTPS-посилання на зустріч</span><input name="meetingUrl" type="url" value="${esc(item.meetingUrl||'')}"></label>`,async form=>{await teacherApi.updateClass(id,{title:form.get('title'),description:form.get('description'),lessonId:form.get('lessonId')||null,meetingUrl:form.get('meetingUrl')||null,meetingProvider:'External'});await refresh('Заняття оновлено')});}
 if(name==='reschedule-class'){const item=state.data.sessions.find(x=>x.id===id);openModal('Перенести заняття',`<label class="field"><span>Новий початок</span><input name="startsAt" type="datetime-local" value="${localValue(item.startsAt)}" required></label><label class="field"><span>Новий кінець</span><input name="endsAt" type="datetime-local" value="${localValue(item.endsAt)}" required></label><label class="field"><span>Причина для сповіщення</span><textarea name="reason" required></textarea></label>`,async form=>{await teacherApi.reschedule(id,{startsAt:new Date(form.get('startsAt')).toISOString(),endsAt:new Date(form.get('endsAt')).toISOString(),reason:form.get('reason')});await refresh('Заняття перенесено, подію сповіщення підготовлено')});}
 if(name==='new-homework'){const group=state.data.groups[0];openModal('Нове домашнє завдання',`<div class="form-grid"><label class="field"><span>Група</span><select name="groupId">${state.data.groups.map(g=>`<option value="${g.id}">${esc(g.name)}</option>`)}</select></label><label class="field"><span>Повʼязане заняття</span><select name="classSessionId"><option value="">Без заняття</option>${state.data.sessions.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`)}</select></label></div><label class="field"><span>Назва</span><input name="title" required></label><label class="field"><span>Інструкції</span><textarea name="instructions" required></textarea></label><div class="form-grid"><label class="field"><span>Дедлайн</span><input name="dueAt" type="datetime-local" required></label><label class="field"><span>XP за виконання</span><input name="xpReward" type="number" min="0" max="10000" value="100" required></label></div><div class="form-grid"><label class="field"><span>Ресурс до завдання</span><input name="resourceTitle" maxlength="180" placeholder="Назва матеріалу"></label><label class="field"><span>HTTPS-посилання</span><input name="resourceUrl" type="url" placeholder="https://…"></label></div><label class="field"><span>Статус</span><select name="status"><option value="draft">Зберегти чернеткою</option><option value="published">Опублікувати зараз</option></select></label>`,async form=>{const selected=state.data.groups.find(g=>g.id===form.get('groupId'))||group,status=form.get('status'),input={groupId:selected.id,courseId:selected.courseId,title:form.get('title'),instructions:form.get('instructions'),dueAt:new Date(form.get('dueAt')).toISOString(),xpReward:Number(form.get('xpReward')),status};if(form.get('classSessionId'))input.classSessionId=form.get('classSessionId');if(form.get('resourceTitle')&&form.get('resourceUrl'))input.resources=[{kind:'link',title:form.get('resourceTitle'),url:form.get('resourceUrl')}];if(status==='published')input.publishAt=new Date().toISOString();await teacherApi.createHomework(input);await refresh('Домашню роботу збережено')});}
 if(name==='edit-report'){const report=state.data.reports.find(x=>x.id===id);openModal(`Звіт · ${report.studentFirstName}`,`<div class="report-preview"><span>XP <b>${esc(report.payload.xpEarned??'—')}</b></span><span>Проєкт <b>${esc(report.payload.projectProgress??'—')}%</b></span><span>Заняття <b>${esc(report.payload.classesAttended??'—')}/${esc(report.payload.classesScheduled??'—')}</b></span></div><label class="field"><span>Спостереження викладача</span><textarea name="teacherComment" required>${esc(report.teacherComment)}</textarea></label><label class="field"><span>Стан</span><select name="status"><option value="draft">Чернетка</option><option value="ready_for_review" ${report.status==='ready_for_review'?'selected':''}>Готовий до погодження</option></select></label><p class="privacy-note">Надсилання неможливе без окремої дії «Погодити звіт».</p>`,async form=>{await teacherApi.saveReport(id,{teacherComment:form.get('teacherComment'),status:form.get('status')});await refresh('Звіт збережено')});}
 if(name==='edit-portfolio'){const item=state.data.students.flatMap(s=>s.portfolio?.projects||[]).find(x=>x.id===id);openModal('Уточнити роботу в портфоліо',`<label class="field"><span>Назва</span><input name="title" value="${esc(item.title)}" required></label><label class="field"><span>Короткий опис</span><textarea name="shortDescription">${esc(item.shortDescription)}</textarea></label><label class="field"><span>Рефлексія учня</span><textarea name="reflection">${esc(item.reflection)}</textarea></label><label class="field"><span>Чого навчився</span><textarea name="learned">${esc(item.learned)}</textarea></label><p class="privacy-note">Зміни не публікують портфоліо автоматично.</p>`,async form=>{await teacherApi.updatePortfolio(id,{title:form.get('title'),shortDescription:form.get('shortDescription'),reflection:form.get('reflection'),learned:form.get('learned')});await refresh('Елемент портфоліо оновлено')});}
 }catch(error){toast(error.message,true)}finally{state.saving=false}}

window.addEventListener('hashchange',parseRoute);
window.addEventListener('beforeunload',event=>{if(state.dirty){event.preventDefault();event.returnValue=''}});
async function boot(){try{await teacherApi.authenticate();state.data=await teacherApi.workspace();parseRoute()}catch(error){if(error.status===401||error.status===403){location.replace('/login.html?next=%2Fteacher.html');return}app.innerHTML=`<div class="fatal"><span>TEACHER OS</span><h1>Доступ не відкрито</h1><p>${esc(error.message)}</p><small>Спробуйте оновити сторінку або зверніться до адміністратора.</small></div>`}}
boot();
